    fields = {"entry_lot_label": "lot", "entry_product_label": "product", "conference_label": "volume"}
    for rule in rule_model.all_objects.filter(deleted_at__isnull=True):
        alive = template_model.all_objects.filter(account_id=rule.account_id, is_active=True, deleted_at__isnull=True)
        changes = {}
        for field, subject in fields.items():
            of_kind = alive.filter(subject=subject)
            found = of_kind.filter(is_default=True).first() or of_kind.order_by("-is_system", "name").first()
            if found is not None:
                changes[field] = found
        if changes:
            rule_model.all_objects.filter(pk=rule.pk).update(**changes)


